// Normalize Twilio or CallRail call-completion payloads.
// Unknown providers fail closed: is_valid_missed = false.

const item = $input.first().json;
const raw = item.body || item;

const TWILIO_MISSED = new Set(['no-answer', 'busy', 'failed', 'canceled']);

let normalized = {
  event_id: '',
  caller_number: '',
  caller_name: 'Unknown Caller',
  business_number: '',
  call_status: 'unknown',
  source: 'unknown',
  is_valid_missed: false,
  timestamp: new Date().toISOString(),
};

if (raw.CallStatus !== undefined || raw.CallSid !== undefined) {
  const callerNum = raw.Caller || raw.From || '';
  const status = String(raw.CallStatus || '').toLowerCase();

  normalized = {
    event_id: raw.CallSid || '',
    caller_number: callerNum,
    caller_name: raw.CallerName || 'Unknown Caller',
    business_number: raw.Called || raw.To || '',
    call_status: status || 'unknown',
    source: 'twilio',
    is_valid_missed: TWILIO_MISSED.has(status) && callerNum !== '',
    timestamp: raw.Timestamp ? new Date(raw.Timestamp).toISOString() : new Date().toISOString(),
  };
} else if (
  raw.id !== undefined ||
  raw.customer_phone_number !== undefined ||
  raw.answered !== undefined ||
  raw.call_type !== undefined
) {
  const callerNum =
    raw.customer_phone_number ||
    raw.caller_phone_number ||
    raw.caller_number ||
    '';

  const answered = raw.answered;
  const callType = String(raw.call_type || '').toLowerCase();
  const direction = String(raw.direction || 'inbound').toLowerCase();

  const explicitlyMissed =
    answered === false ||
    callType === 'missed' ||
    callType === 'voicemail' ||
    callType === 'abandonded' ||
    callType === 'abandoned';

  normalized = {
    event_id: raw.id || '',
    caller_number: callerNum,
    caller_name: raw.customer_name || raw.caller_name || 'Unknown Caller',
    business_number: raw.tracking_phone_number || raw.business_phone_number || '',
    call_status: callType || (answered === false ? 'missed' : answered === true ? 'answered' : 'unknown'),
    source: 'callrail',
    is_valid_missed: direction === 'inbound' && explicitlyMissed && callerNum !== '',
    timestamp: raw.start_time ? new Date(raw.start_time).toISOString() : new Date().toISOString(),
  };
}

return [{ json: normalized }];

const TIMEZONE = $vars.BUSINESS_TIMEZONE || 'America/Chicago';
const BUSINESS_HOURS_START = parseInt($vars.BUSINESS_HOURS_START || '8', 10);
const BUSINESS_HOURS_END = parseInt($vars.BUSINESS_HOURS_END || '17', 10);
const WORK_DAYS = ($vars.BUSINESS_WORK_DAYS || '1,2,3,4,5').split(',').map(Number);

const item = $input.first().json;
const eventTime = item.timestamp ? new Date(item.timestamp) : new Date();

const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: TIMEZONE,
  hour12: false,
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
}).formatToParts(eventTime);

const lookup = Object.fromEntries(parts.map(p => [p.type, p.value]));
const weekdayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const day = weekdayMap[lookup.weekday];
const hour = parseInt(lookup.hour, 10);

const isAfterHours =
  !WORK_DAYS.includes(day) ||
  hour < BUSINESS_HOURS_START ||
  hour >= BUSINESS_HOURS_END;

return [{ json: { ...item, is_after_hours: isAfterHours } }];

const BUSINESS_NAME = $vars.BUSINESS_NAME || 'Our team';
const BOOKING_URL = $vars.BUSINESS_BOOKING_URL || '';
const ALERT_EMAIL = $vars.BUSINESS_ALERT_EMAIL || '';
const SMS_NUMBER = $vars.BUSINESS_SMS_NUMBER || '';

const item = $input.first().json;

const rawFirst = (item.caller_name || '').trim().split(/\s+/)[0];
const firstName =
  rawFirst &&
  !['Unknown', 'Anonymous', 'Unavailable'].includes(rawFirst)
    ? rawFirst
    : '';

const greeting = firstName ? `Hi ${firstName}` : 'Hi';
const booking = BOOKING_URL ? ` You can book here: ${BOOKING_URL}` : '';

const smsText = item.is_after_hours
  ? `${greeting}, this is ${BUSINESS_NAME}. Sorry we missed your call — we're currently closed.${booking} Reply STOP to opt out.`
  : `${greeting}, this is ${BUSINESS_NAME}. Sorry we missed your call.${booking} Reply here and we'll get back to you. Reply STOP to opt out.`;

return [{
  json: {
    ...item,
    sms_text: smsText,
    business_alert_email: ALERT_EMAIL,
    business_sms_number: SMS_NUMBER,
    business_name: BUSINESS_NAME,
    booking_url: BOOKING_URL,
  }
}];

