// Lightweight idempotency guard for a reusable template.
// Stores recently-seen event IDs in workflow static data for 24 hours.
// For high-volume / multi-worker production, replace this with a persistent Data Table, DB, or Redis.

const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.missedCallSeen = store.missedCallSeen || {};

const now = Date.now();
const ttlMs = 24 * 60 * 60 * 1000;

// Prune expired keys.
for (const [key, seenAt] of Object.entries(store.missedCallSeen)) {
  if (now - Number(seenAt) > ttlMs) delete store.missedCallSeen[key];
}

const fallbackKey = `${item.source}:${item.caller_number}:${item.timestamp}`;
const eventKey = item.event_id || fallbackKey;
const isDuplicate = Boolean(store.missedCallSeen[eventKey]);

if (!isDuplicate) {
  store.missedCallSeen[eventKey] = now;
}

return [{ json: { ...item, event_key: eventKey, is_duplicate: isDuplicate } }];
